/****************************************************************************
 * app/velaguard/modbus_port_openvela.h
 *
 * nanoMODBUS 串口适配层公开接口。只负责把字符设备接到
 * nmbs_platform_conf，不含 Modbus 协议逻辑。
 ****************************************************************************/

#ifndef __APPS_VELAGUARD_MODBUS_PORT_OPENVELA_H
#define __APPS_VELAGUARD_MODBUS_PORT_OPENVELA_H

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdint.h>

#include "nanomodbus/nanomodbus.h"

/****************************************************************************
 * Public Types
 ****************************************************************************/

struct vg_modbus_port_s
{
  int fd;
};

/****************************************************************************
 * Public Function Prototypes
 ****************************************************************************/

/* 打开串口并设 raw 模式（波特率跟随驱动，UART7 当前为 9600 8N1）。 */

int vg_modbus_port_open(FAR struct vg_modbus_port_s *port,
                        FAR const char *devpath);

void vg_modbus_port_close(FAR struct vg_modbus_port_s *port);

/* 把本 port 填进 nanoMODBUS 的 platform_conf（RTU + read/write/flush）。 */

void vg_modbus_port_bind(FAR struct vg_modbus_port_s *port,
                         FAR nmbs_platform_conf *pc);

#endif /* __APPS_VELAGUARD_MODBUS_PORT_OPENVELA_H */

/****************************************************************************
 * app/velaguard/modbus_port_openvela.c
 *
 * nanoMODBUS 串口适配层：把 /dev/rs485 接到 nmbs_platform_conf 的
 * read/write/flush。不含任何 Modbus 协议逻辑。
 *
 * 传输契约（nanoMODBUS v1.23.0）：
 *   - 阻塞到收满/发完 count 字节，或 byte_timeout_ms 到期；
 *   - byte_timeout_ms < 0 无限等待，== 0 非阻塞试一次；
 *   - 返回实际字节数；< 0 为传输错误；[0, count-1] 视为超时。
 *
 * DE/RE 由 NuttX UART7 RS485 驱动自动切换。tcdrain 之后补一段短延时，
 * 规避已知问题：uart_tcdrain 不等移位寄存器发完（见
 * docs/velaguard-bringup-known-issues.md §4）。
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <fcntl.h>
#include <poll.h>
#include <stdint.h>
#include <termios.h>
#include <unistd.h>

#include "modbus_port_openvela.h"

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static int32_t vg_modbus_now_ms(void)
{
  struct timespec ts;

  clock_gettime(CLOCK_MONOTONIC, &ts);
  return (int32_t)(ts.tv_sec * 1000L + ts.tv_nsec / 1000000L);
}

/* 9600 8N1 下一个字符约 1.15ms；3.5 字符时间 ≈ 4ms。取 5ms 覆盖
 * tcdrain 未等 TC 的尾巴，同时满足 RTU 帧间隔。
 */

#define VG_MODBUS_TX_TAIL_US 5000

static int32_t vg_modbus_port_read(uint8_t *buf, uint16_t count,
                                   int32_t byte_timeout_ms, void *arg)
{
  FAR struct vg_modbus_port_s *port = arg;
  uint16_t got = 0;
  int32_t deadline = 0;
  bool infinite = (byte_timeout_ms < 0);

  if (port == NULL || port->fd < 0 || buf == NULL)
    {
      return -1;
    }

  if (count == 0)
    {
      return 0;
    }

  if (!infinite)
    {
      deadline = vg_modbus_now_ms() + byte_timeout_ms;
    }

  while (got < count)
    {
      struct pollfd pfd;
      int remain;
      int ret;
      ssize_t n;

      if (infinite)
        {
          remain = 1000;
        }
      else
        {
          remain = (int)(deadline - vg_modbus_now_ms());
          if (remain < 0)
            {
              remain = 0;
            }
        }

      pfd.fd      = port->fd;
      pfd.events  = POLLIN;
      pfd.revents = 0;

      ret = poll(&pfd, 1, remain);
      if (ret < 0)
        {
          if (errno == EINTR)
            {
              continue;
            }

          return -1;
        }

      if (ret == 0)
        {
          if (infinite)
            {
              continue;
            }

          return got;
        }

      n = read(port->fd, buf + got, count - got);
      if (n > 0)
        {
          got += (uint16_t)n;
          continue;
        }

      if (n == 0)
        {
          return got;
        }

      if (errno == EAGAIN || errno == EINTR)
        {
          continue;
        }

      return -1;
    }

  return got;
}

static int32_t vg_modbus_port_write(const uint8_t *buf, uint16_t count,
                                    int32_t byte_timeout_ms, void *arg)
{
  FAR struct vg_modbus_port_s *port = arg;
  uint16_t sent = 0;
  int32_t deadline = 0;
  bool infinite = (byte_timeout_ms < 0);

  if (port == NULL || port->fd < 0 || buf == NULL)
    {
      return -1;
    }

  if (count == 0)
    {
      return 0;
    }

  if (!infinite)
    {
      deadline = vg_modbus_now_ms() + byte_timeout_ms;
    }

  while (sent < count)
    {
      struct pollfd pfd;
      int remain;
      int ret;
      ssize_t n;

      if (infinite)
        {
          remain = 1000;
        }
      else
        {
          remain = (int)(deadline - vg_modbus_now_ms());
          if (remain < 0)
            {
              remain = 0;
            }
        }

      pfd.fd      = port->fd;
      pfd.events  = POLLOUT;
      pfd.revents = 0;

      ret = poll(&pfd, 1, remain);
      if (ret < 0)
        {
          if (errno == EINTR)
            {
              continue;
            }

          return -1;
        }

      if (ret == 0)
        {
          if (infinite)
            {
              continue;
            }

          return sent;
        }

      n = write(port->fd, buf + sent, count - sent);
      if (n > 0)
        {
          sent += (uint16_t)n;
          continue;
        }

      if (n == 0)
        {
          return sent;
        }

      if (errno == EAGAIN || errno == EINTR)
        {
          continue;
        }

      return -1;
    }

  if (tcdrain(port->fd) < 0)
    {
      return -1;
    }

  usleep(VG_MODBUS_TX_TAIL_US);
  return sent;
}

static void vg_modbus_port_flush(nmbs_t *nmbs, void *arg)
{
  FAR struct vg_modbus_port_s *port = arg;
  uint8_t tmp[32];

  UNUSED(nmbs);

  if (port == NULL || port->fd < 0)
    {
      return;
    }

  for (; ; )
    {
      struct pollfd pfd;
      ssize_t n;

      pfd.fd      = port->fd;
      pfd.events  = POLLIN;
      pfd.revents = 0;

      if (poll(&pfd, 1, 0) <= 0)
        {
          break;
        }

      n = read(port->fd, tmp, sizeof(tmp));
      if (n <= 0)
        {
          break;
        }
    }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int vg_modbus_port_open(FAR struct vg_modbus_port_s *port,
                        FAR const char *devpath)
{
  struct termios tio;
  int fd;

  if (port == NULL || devpath == NULL)
    {
      return -1;
    }

  fd = open(devpath, O_RDWR);
  if (fd < 0)
    {
      return -1;
    }

  if (tcgetattr(fd, &tio) < 0)
    {
      close(fd);
      return -1;
    }

  cfmakeraw(&tio);
  cfsetispeed(&tio, B9600);
  cfsetospeed(&tio, B9600);
  tio.c_cflag |= CLOCAL | CREAD;

  if (tcsetattr(fd, TCSANOW, &tio) < 0)
    {
      close(fd);
      return -1;
    }

  tcflush(fd, TCIOFLUSH);
  port->fd = fd;
  return 0;
}

void vg_modbus_port_close(FAR struct vg_modbus_port_s *port)
{
  if (port == NULL || port->fd < 0)
    {
      return;
    }

  close(port->fd);
  port->fd = -1;
}

void vg_modbus_port_bind(FAR struct vg_modbus_port_s *port,
                         FAR nmbs_platform_conf *pc)
{
  nmbs_platform_conf_create(pc);
  pc->transport = NMBS_TRANSPORT_RTU;
  pc->read      = vg_modbus_port_read;
  pc->write     = vg_modbus_port_write;
  pc->flush     = vg_modbus_port_flush;
  pc->arg       = port;
}

/****************************************************************************
 * app/velaguard/modbus_collector.c
 *
 * vgmodbus - Modbus RTU 主站 bring-up 工具（NSH 命令）。
 *
 * 用途：阶段 2 最小闭环。经 nanoMODBUS client 周期读一个从站的
 * Holding / Input Register，打印数值与连续失败次数（后续离线判定的输入）。
 *
 * 用法（NSH）：
 *   vgmodbus [-d <dev>] [-a <addr>] [-r <start>] [-c <qty>]
 *            [-t 3|4] [-n <loops>] [-i <secs>]
 *
 * 缺省：dev=/dev/rs485, addr=1, start=0, qty=4, FC=3 (holding),
 *       loops=0（一直轮询）, interval=1s。
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include "modbus_port_openvela.h"

#ifndef VGMODBUS_DEFAULT_DEV
#  define VGMODBUS_DEFAULT_DEV "/dev/rs485"
#endif

#define VGMODBUS_MAX_REGS     32
#define VGMODBUS_READ_TO_MS   500
#define VGMODBUS_BYTE_TO_MS   20

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct vgmodbus_cfg_s
{
  FAR const char *dev;
  uint8_t         addr;
  uint16_t        start;
  uint16_t        qty;
  uint8_t         fc;          /* 3=holding, 4=input */
  unsigned int    loops;       /* 0 = forever */
  unsigned int    interval_s;
};

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static void show_usage(FAR const char *prog)
{
  fprintf(stderr,
          "Usage: %s [-d <dev>] [-a <addr>] [-r <start>] [-c <qty>]\n"
          "          [-t 3|4] [-n <loops>] [-i <secs>]\n"
          "Defaults: dev=%s addr=1 start=0 qty=4 fc=3 loops=0 interval=1s\n"
          "  -t 3  Read Holding Registers (FC 03)\n"
          "  -t 4  Read Input Registers   (FC 04)\n"
          "  -n 0  poll forever\n",
          prog, VGMODBUS_DEFAULT_DEV);
}

static int parse_args(int argc, FAR char *argv[],
                      FAR struct vgmodbus_cfg_s *cfg)
{
  int opt;
  long v;

  memset(cfg, 0, sizeof(*cfg));
  cfg->dev        = VGMODBUS_DEFAULT_DEV;
  cfg->addr       = 1;
  cfg->start      = 0;
  cfg->qty        = 4;
  cfg->fc         = 3;
  cfg->loops      = 0;
  cfg->interval_s = 1;

  optind = 1;

  while ((opt = getopt(argc, argv, "d:a:r:c:t:n:i:")) != ERROR)
    {
      switch (opt)
        {
          case 'd':
            cfg->dev = optarg;
            break;

          case 'a':
            v = strtol(optarg, NULL, 0);
            if (v < 1 || v > 247)
              {
                fprintf(stderr, "ERROR: addr must be 1..247\n");
                return ERROR;
              }

            cfg->addr = (uint8_t)v;
            break;

          case 'r':
            v = strtol(optarg, NULL, 0);
            if (v < 0 || v > 65535)
              {
                fprintf(stderr, "ERROR: start register out of range\n");
                return ERROR;
              }

            cfg->start = (uint16_t)v;
            break;

          case 'c':
            v = strtol(optarg, NULL, 0);
            if (v < 1 || v > VGMODBUS_MAX_REGS)
              {
                fprintf(stderr, "ERROR: qty must be 1..%d\n",
                        VGMODBUS_MAX_REGS);
                return ERROR;
              }

            cfg->qty = (uint16_t)v;
            break;

          case 't':
            v = strtol(optarg, NULL, 0);
            if (v != 3 && v != 4)
              {
                fprintf(stderr, "ERROR: -t must be 3 (holding) or 4 (input)\n");
                return ERROR;
              }

            cfg->fc = (uint8_t)v;
            break;

          case 'n':
            v = strtol(optarg, NULL, 0);
            if (v < 0)
              {
                fprintf(stderr, "ERROR: loops must be >= 0\n");
                return ERROR;
              }

            cfg->loops = (unsigned int)v;
            break;

          case 'i':
            v = strtol(optarg, NULL, 0);
            if (v < 0)
              {
                fprintf(stderr, "ERROR: interval must be >= 0\n");
                return ERROR;
              }

            cfg->interval_s = (unsigned int)v;
            break;

          default:
            show_usage(argv[0]);
            return ERROR;
        }
    }

  return OK;
}

static nmbs_error do_read(FAR nmbs_t *nmbs, FAR const struct vgmodbus_cfg_s *cfg,
                          FAR uint16_t *regs)
{
  if (cfg->fc == 4)
    {
      return nmbs_read_input_registers(nmbs, cfg->start, cfg->qty, regs);
    }

  return nmbs_read_holding_registers(nmbs, cfg->start, cfg->qty, regs);
}

static void print_regs(uint8_t addr, uint16_t start, uint16_t qty,
                       FAR const uint16_t *regs)
{
  unsigned int i;

  printf("addr=%u start=%u:", (unsigned int)addr, (unsigned int)start);
  for (i = 0; i < qty; i++)
    {
      printf(" [%u]=%u", (unsigned int)(start + i), (unsigned int)regs[i]);
    }

  printf("\n");
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  struct vgmodbus_cfg_s cfg;
  struct vg_modbus_port_s port;
  nmbs_platform_conf pc;
  nmbs_t nmbs;
  nmbs_error err;
  uint32_t fails = 0;
  unsigned int n = 0;

  if (parse_args(argc, argv, &cfg) != OK)
    {
      return 1;
    }

  port.fd = -1;
  if (vg_modbus_port_open(&port, cfg.dev) < 0)
    {
      fprintf(stderr, "vgmodbus: open %s failed: %d\n", cfg.dev, errno);
      return 1;
    }

  vg_modbus_port_bind(&port, &pc);

  err = nmbs_client_create(&nmbs, &pc);
  if (err != NMBS_ERROR_NONE)
    {
      fprintf(stderr, "vgmodbus: nmbs_client_create: %s\n",
              nmbs_strerror(err));
      vg_modbus_port_close(&port);
      return 1;
    }

  nmbs_set_read_timeout(&nmbs, VGMODBUS_READ_TO_MS);
  nmbs_set_byte_timeout(&nmbs, VGMODBUS_BYTE_TO_MS);
  nmbs_set_destination_rtu_address(&nmbs, cfg.addr);

  printf("vgmodbus: %s addr=%u fc=%u start=%u qty=%u\n",
         cfg.dev, (unsigned int)cfg.addr, (unsigned int)cfg.fc,
         (unsigned int)cfg.start, (unsigned int)cfg.qty);

  for (; ; )
    {
      uint16_t regs[VGMODBUS_MAX_REGS];

      memset(regs, 0, sizeof(regs));
      err = do_read(&nmbs, &cfg, regs);
      if (err == NMBS_ERROR_NONE)
        {
          fails = 0;
          print_regs(cfg.addr, cfg.start, cfg.qty, regs);
        }
      else
        {
          fails++;
          printf("read failed: %s (fails=%lu)\n",
                 nmbs_strerror(err), (unsigned long)fails);
        }

      n++;
      if (cfg.loops != 0 && n >= cfg.loops)
        {
          break;
        }

      if (cfg.interval_s > 0)
        {
          sleep(cfg.interval_s);
        }
    }

  vg_modbus_port_close(&port);
  return (fails == 0) ? 0 : 1;
}

